    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if planet1 and planet2 are recognized planet names
    if planet1.capitalize() not in planets or planet2.capitalize() not in planets:
        return ()

    # Determine the orbits of planet1 and planet2
    orbit1 = planets.index(planet1.capitalize())
    orbit2 = planets.index(planet2.capitalize())

    # Identify the planets between the orbits of planet1 and planet2
    if orbit1 < orbit2:
        result = planets[orbit1 + 1:orbit2]
    else:
        result = planets[orbit2 + 1:orbit1]

    # Order the identified planets by their proximity to the Sun
    result.sort(key=lambda x: planets.index(x))

    return tuple(result)

